-- Datos de ejemplo, portados desde sql/data.sql del proyecto de 2023.
--
-- En el original ese archivo vivía bajo sql/ y NO en el classpath, así que
-- Spring Boot nunca lo ejecutaba: había que pegarlo a mano en la consola de
-- H2. Aquí es una migración de Flyway, de modo que el estado inicial es
-- reproducible y el test end-to-end puede afirmar sobre datos concretos.
--
-- Los ids son explícitos a propósito (la PK es GENERATED BY DEFAULT, no
-- ALWAYS): el test end-to-end necesita poder apuntar a filas conocidas. Las
-- secuencias se reajustan al final.

-- ------------------------------------------------------------------ países --
-- Japón figuraba como 'JA' en los datos de 2023, que no es un código ISO
-- 3166-1 válido. El correcto es 'JP', y ahora el CHECK de la tabla impide
-- que se vuelva a colar.
INSERT INTO country (id, name, iso2, iso3) VALUES
    (1, 'Italia',   'IT', 'ITA'),
    (2, 'México',   'MX', 'MEX'),
    (3, 'Japón',    'JP', 'JPN'),
    (4, 'India',    'IN', 'IND'),
    (5, 'Colombia', 'CO', 'COL');

