-- ----------------------------------------------------------------- recetas --
-- Corrección de datos: en 2023 'Tacos al Pastor' apuntaba a culture_id 1
-- (cocina italiana) y 'Pasta Carbonara' a culture_id 2 (cocina mexicana).
-- Estaban intercambiadas. Como el texto de las recetas está en inglés y la
-- interfaz en español, este corpus es además el caso de prueba real del
-- modelo de embeddings multilingüe de la Fase 4.
INSERT INTO recipe (id, name, slug, description, culture_id, prep_time_minutes, servings, difficulty) VALUES
    (1, 'Tacos al Pastor', 'tacos-al-pastor', 'Cerdo marinado en achiote, servido en tortilla de maíz con piña.',        2, 150, 4, 'MEDIA'),
    (2, 'Pasta Carbonara', 'pasta-carbonara', 'Pasta romana con huevo, queso curado y guanciale. Sin nata.',             1,  25, 2, 'FACIL'),
    (3, 'Sushi Rolls',     'sushi-rolls',     'Rollos de arroz avinagrado y alga nori con relleno variable.',            3,  60, 4, 'DIFICIL'),
    (4, 'Chicken Curry',   'chicken-curry',   'Pollo guisado en leche de coco con una base de especias tostadas.',       4,  45, 4, 'FACIL'),
    (5, 'Bandeja Paisa',   'bandeja-paisa',   'Plato antioqueño abundante: frijoles, arroz, carnes, plátano y huevo.',   5,  90, 2, 'MEDIA');

-- Los pasos vuelven a ser filas, como en el UML original. En 2023 esto era un
-- único @Lob de ~1500 caracteres que se cargaba entero en cada listado.
-- duration_seconds sólo se rellena cuando el texto menciona un tiempo; es lo
-- que alimenta los temporizadores del modo cocina.
INSERT INTO recipe_step (recipe_id, position, instruction, duration_seconds) VALUES
    (1, 1, 'Mezclar la pasta de achiote, el vinagre blanco, el aceite, el orégano seco, el comino, el pimentón ahumado, la sal, la pimienta negra y el ajo picado hasta formar una marinada homogénea.', NULL),
    (1, 2, 'Añadir el cerdo en lonchas finas y remover hasta cubrirlo por completo. Tapar y refrigerar al menos 2 horas, mejor toda la noche.', 7200),
    (1, 3, 'Calentar la plancha a fuego medio-alto y engrasarla ligeramente.', NULL),
    (1, 4, 'Ensartar el cerdo en brochetas y asar de 10 a 12 minutos, girando de vez en cuando, hasta que esté hecho y ligeramente tostado. Pincelar con zumo de piña mientras se asa.', 660),
    (1, 5, 'Retirar de las brochetas, dejar reposar unos minutos y cortar en tiras finas.', NULL),
    (1, 6, 'Calentar las tortillas de maíz en un comal. Servir el cerdo encima con cebolla, cilantro y piña, y terminar con lima exprimida.', NULL),

    (2, 1, 'Cocer la pasta en abundante agua con sal hasta que esté al dente. Reservar media taza del agua de cocción antes de escurrir.', NULL),
    (2, 2, 'Mientras tanto, dorar el guanciale en una sartén amplia a fuego medio hasta que suelte su grasa y quede crujiente, unos 5 a 7 minutos.', 360),
    (2, 3, 'Batir los huevos con el parmesano y el pecorino rallados. Salpimentar.', NULL),
    (2, 4, 'Retirar la sartén del fuego y dejar que baje de temperatura unos segundos. Añadir la pasta escurrida y remover para que se impregne de la grasa.', NULL),
    (2, 5, 'Verter la mezcla de huevo y queso removiendo rápido: el calor residual la cuaja en una crema. Si espesa demasiado, aflojar con el agua de cocción reservada.', NULL),
    (2, 6, 'Servir de inmediato, con pimienta negra recién molida.', NULL),

    (3, 1, 'Lavar el arroz para sushi hasta que el agua salga clara y cocerlo según las instrucciones del paquete.', NULL),
    (3, 2, 'Pasar el arroz a un bol amplio y, todavía templado, mezclarlo con el vinagre de sushi con movimientos suaves. Dejar enfriar por completo.', NULL),
    (3, 3, 'Cortar los rellenos en tiras largas y finas: pepino, aguacate, salmón ahumado o atún.', NULL),
    (3, 4, 'Colocar una lámina de nori sobre la esterilla y extender el arroz dejando unos dos centímetros libres en el borde superior.', NULL),
    (3, 5, 'Disponer el relleno en línea sobre el arroz y enrollar con la esterilla apretando de forma uniforme. Sellar el borde con un poco de agua.', NULL),
    (3, 6, 'Cortar cada rollo en porciones con un cuchillo afilado, mojándolo entre corte y corte. Servir con soja, wasabi y jengibre encurtido.', NULL),

    (4, 1, 'Calentar el aceite en una sartén amplia y pochar la cebolla picada hasta que esté blanda y dorada, unos 5 minutos.', 300),
    (4, 2, 'Añadir el ajo y el jengibre rallado y sofreír 1 o 2 minutos más, hasta que suelten aroma.', 90),
    (4, 3, 'Incorporar la mezcla de especias (curry, comino, cilantro molido, cúrcuma y cayena) y remover para que se tueste y cubra el sofrito.', NULL),
    (4, 4, 'Añadir el pollo troceado y sellarlo por todos lados, de 5 a 7 minutos.', 360),
    (4, 5, 'Verter la leche de coco, el caldo, el concentrado de tomate y un punto de azúcar moreno. Remover para integrar.', NULL),
    (4, 6, 'Llevar a ebullición suave, bajar el fuego y cocer tapado de 20 a 25 minutos, hasta que el pollo esté tierno. Rectificar de sal y servir con arroz.', 1350),

    (5, 1, 'Cocer por separado el arroz blanco y los frijoles rojos según sus instrucciones.', NULL),
    (5, 2, 'Freír el tocino en una sartén amplia hasta que esté crujiente y reservarlo.', NULL),
    (5, 3, 'En la misma sartén, cocinar la carne molida y el chorizo hasta que estén bien hechos. Reservar.', NULL),
    (5, 4, 'Freír las tajadas de plátano maduro en aceite caliente hasta que se doren.', NULL),
    (5, 5, 'Freír los huevos al gusto, normalmente con la yema líquida.', NULL),
    (5, 6, 'Montar la bandeja: arroz, frijoles, tocino, carne, chorizo, plátano, huevo, aguacate y arepa. Napar con hogao y servir de inmediato.', NULL);

