-- ------------------------------------------------------------------ secuencias --
-- Se insertaron ids explícitos, así que hay que adelantar las secuencias de
-- identidad o el primer INSERT de la aplicación chocaría con una PK existente.
SELECT setval(pg_get_serial_sequence('country', 'id'),                (SELECT max(id) FROM country));
SELECT setval(pg_get_serial_sequence('gastronomic_culture', 'id'),    (SELECT max(id) FROM gastronomic_culture));
SELECT setval(pg_get_serial_sequence('gastronomic_category', 'id'),   (SELECT max(id) FROM gastronomic_category));
SELECT setval(pg_get_serial_sequence('representative_product', 'id'), (SELECT max(id) FROM representative_product));
SELECT setval(pg_get_serial_sequence('restaurant', 'id'),             (SELECT max(id) FROM restaurant));
SELECT setval(pg_get_serial_sequence('michelin_star', 'id'),          (SELECT max(id) FROM michelin_star));
SELECT setval(pg_get_serial_sequence('recipe', 'id'),                 (SELECT max(id) FROM recipe));
SELECT setval(pg_get_serial_sequence('dish_multimedia', 'id'),        (SELECT max(id) FROM dish_multimedia));
SELECT setval(pg_get_serial_sequence('recipe_step', 'id'),            (SELECT max(id) FROM recipe_step));
SELECT setval(pg_get_serial_sequence('ingredient', 'id'),             (SELECT max(id) FROM ingredient));
